EXPECTED_CHECKS = 137

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *_):
        pass

    def do_GET(self):
        if self.path == '/echo':
            data = json.dumps({'bytes': self.headers.get('X-Bytes', '').encode('latin1').hex(),
                               'multi': ', '.join(self.headers.get_all('X-Multi') or [])}).encode()
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('X-Bytes', '\x80\xE9\xFF')
        else:
            resources = {'/': ('text/html; charset=utf-8', PAGE),
                         '/worker.js': ('text/javascript; charset=utf-8', WORKER),
                         '/frame': ('text/html; charset=utf-8', '<!doctype html><html><body>Headers realm</body></html>')}
            content_type, text = resources.get(self.path, ('text/plain', 'not found'))
            data = text.encode()
            self.send_response(200 if self.path in resources else 404)
            self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--binary', required=True, type=Path)
    args = parser.parse_args()
    binary = args.binary.resolve(strict=True)
    server = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        with tempfile.TemporaryDirectory(prefix='lumen-fetch-headers-') as profile:
            env = {key: value for key, value in os.environ.items() if not key.startswith('LUMEN_')}
            env.update(LUMEN_PROFILE_DIR=profile, LUMEN_CONSOLE='1', JSRUN_UNTIL_ATTR='data-fetch-headers-done')
            result = subprocess.run([str(binary), f'http://127.0.0.1:{server.server_port}/', '12000'],
                                    text=True, capture_output=True, env=env, timeout=18)
        sys.stdout.write(result.stdout)
        sys.stderr.write(result.stderr)
        transcript = result.stdout + result.stderr
        summaries = [json.loads(line.split('FETCH_HEADERS_RESULTS ', 1)[1]) for line in transcript.splitlines() if 'FETCH_HEADERS_RESULTS ' in line]
        checks = [json.loads(line.split('FETCH_HEADERS_CHECK ', 1)[1]) for line in transcript.splitlines() if 'FETCH_HEADERS_CHECK ' in line]
        if result.returncode or len(summaries) != 1 or len(checks) != EXPECTED_CHECKS or sorted(c['index'] for c in checks) != list(range(EXPECTED_CHECKS)):
            print('FETCH_HEADERS_INFRASTRUCTURE missing or duplicate fixture results')
            return 2
        report = summaries[0]
        if report['total'] != EXPECTED_CHECKS or report['passed'] != sum(c['passed'] is True for c in checks):
            return 2
        print(f"RESULTS fetch-headers {'PASS' if report['passed'] == EXPECTED_CHECKS else 'FAIL'} ({report['passed']}/{EXPECTED_CHECKS} checks)")
        return 0 if report['passed'] == EXPECTED_CHECKS else 1
    finally:
        server.shutdown()
        server.server_close()
        thread.join(timeout=2)


if __name__ == '__main__':
    raise SystemExit(main())
